// Authored translated/interpreted overlap and exact-build natural checkpoints.
#include "pce/checkpoint.hpp"
#include "pce/checkpoint_file.hpp"
#include "pce/code_capture.hpp"
#include "pce/sector.hpp"
#include "active_irq_support.hpp"
#include <filesystem>
#include <functional>
#include <memory>

namespace {
using namespace active_irq;
struct Provider:pce::SectorProvider{std::shared_ptr<pce::SectorProvider>source;unsigned reads=0;std::function<void(unsigned)>on_read;explicit Provider(const char*path):source(pce::open_sector_provider(path)){}const pce::CdToc&toc()const override{return source->toc();}pce::Sector read(std::uint32_t lba)override{++reads;if(on_read)on_read(lba);return source->read(lba);}};
struct Witness{Source source;Row values;};
struct Record{Source source;Row before;std::uint64_t ticks,waits;unsigned vector,causes;Observation after;std::map<std::string,std::int64_t>active_before;};
struct Adapter{
 std::unique_ptr<pce::Bus>bus=std::make_unique<pce::Bus>();pce::Cpu cpu;bool native,window=false;const ActiveIrqCase&recipe;std::shared_ptr<Provider>provider;std::unique_ptr<pce::CodeCapture>capture;Work work;std::map<Source,std::uint64_t>sources;std::vector<Record>journal;std::vector<Witness>witnesses;std::uint64_t target_wait_origin=0;
 Adapter(const char*rom,const char*cue,bool n,const ActiveIrqCase&c):native(n),recipe(c),provider(std::make_shared<Provider>(cue)){
  bus->configure_system_card(pce::SystemCardProfile::standard,reset_probe::rom(rom));bus->enable_video();bus->enable_interrupts();bus->enable_cd_transport();bus->enable_adpcm();bus->cd.set_sector_provider(provider);bus->power_on_cpu(cpu,0,0);
  provider->on_read=[this](unsigned lba){const auto&v=bus->vdc;auto source=current_source();Row values{cpu.ticks,cpu.vdc_wait_ticks,v.vram_dma_pending,v.pending_vram_read?1u:0u,cpu.p,cpu.irq_entries,bus->adpcm.half_irq,bus->adpcm.end_irq,bus->adpcm.length};witnesses.push_back({source,values});require(lba==0,"READ provider requested unexpected LBA");};
 }
 unsigned pc()const{return cpu.pc;}
 Source current_source()const{Source s{cpu.pc,{},{}};for(unsigned i=0;i<8;++i)s.mpr[i]=cpu.mpr[i];auto byte=[&](unsigned address){auto value=bus->peek(pce::Bus::physical(cpu,address));require(bool(value),"Authored source peek");return*value;};const auto n=size(byte(cpu.pc));for(unsigned i=0;i<n;++i)s.bytes.push_back(byte(cpu.pc+i));return s;}
 std::vector<unsigned>wram()const{return{bus->bytes->begin()+0x1f0000,bus->bytes->begin()+0x1f2000};}
 std::vector<unsigned>ram()const{return{bus->adpcm.ram.begin(),bus->adpcm.ram.end()};}
 std::vector<unsigned>vram()const{return{bus->vdc.vram->begin(),bus->vdc.vram->end()};}
 std::map<std::string,std::int64_t>active()const{const auto&v=bus->vdc;const auto&r=v.raster;return{{"hpos",r.hclock},{"vpos",r.vdc_line},{"hstate",r.h_state},{"vstate",r.v_state},{"hremaining",r.h_remaining},{"raster",r.raster_line},{"sprite_count",v.sprite_count},{"bg_start",v.load_bg_start_clock},{"bg_end",v.load_bg_end_clock},{"hsync",v.hsync_start_clock},{"sat_pending",v.satb_pending},{"burst",v.sprite_burst},{"latched_cr",v.sprite_control},{"latched_mwr",v.sprite_mode},{"cr",v.reg[5]},{"mwr",v.reg[9]},{"rcr",v.reg[6]},{"divider",r.divider},{"carry",v.vram_cpu_cycles}};}
 Observation observe()const{const auto&a=bus->adpcm;const auto&c=bus->cd;const auto&v=bus->vdc;Observation o;
  o.values={cpu.pc,cpu.a,cpu.x,cpu.y,cpu.sp,cpu.p,cpu.clock_divisor,cpu.ticks,cpu.irq_entries,cpu.rti_steps,bus->irq.mask,bus->irq_requests(),c.interrupt_enable,c.interrupt_active,c.scsi.signals,a.dma,a.length,a.write_address,a.half_irq,a.end_irq,a.dma_bytes,a.write_deadline?1u:0u,c.irq2()?1u:0u,unsigned(v.status&63)|(v.has_pending_vram()?64u:0u),v.irq1,v.vram_dma_pending,v.pending_vram_read,v.pending_vram_write,v.read_buffer,v.reg[1],v.reg[0],v.reg[16],v.reg[17],v.reg[18],v.vram_bus_latch,static_cast<unsigned>(v.vram_transfer_delay),cpu.vdc_wait_ticks,v.raster.divider,v.dma_words,cpu.irq_sampled,v.selected,cpu.irq_vector};
  o.active=active();o.stack.assign(bus->bytes->begin()+0x1f0100,bus->bytes->begin()+0x1f0200);o.wram=irq_trace::hash(std::span<const std::uint8_t>(bus->bytes->data()+0x1f0000,8192));o.vram=vram_hash(vram());return o;
 }
 void captured(const std::string&path,bool suffix){capture=std::make_unique<pce::CodeCapture>(path,4096);work={};sources.clear();journal.clear();witnesses.clear();window=suffix;}
 void step(){const auto source=current_source();const auto&v=bus->vdc;const Row prior{cpu.a,cpu.x,cpu.y,cpu.sp,cpu.p,cpu.irq_entries,bus->adpcm.half_irq,bus->adpcm.end_irq,v.irq1,bus->cd.irq2()?1u:0u,v.vram_dma_pending,v.pending_vram_read,v.pending_vram_write,cpu.vdc_wait_ticks};const auto phase=source.pc==recipe.target?active():std::map<std::string,std::int64_t>{};const auto ticks=cpu.ticks,waits=cpu.vdc_wait_ticks,entries=cpu.irq_entries,rtis=cpu.rti_steps;const auto before=capture->before(*bus,cpu);
  require((native?pce::generated_step(*bus,cpu,UINT64_MAX):pce::interpret_step(*bus,cpu,UINT64_MAX))==pce::Exit::executed,"Authored active opcode refused; native fallback forbidden");capture->after(before,cpu);++sources[source];++work.instructions;++work.calls;work.clock_ticks+=cpu.ticks-ticks;work.wait_ticks+=cpu.vdc_wait_ticks-waits;work.irqs+=cpu.irq_entries-entries;work.rtis+=cpu.rti_steps-rtis;
  if(block(source.bytes[0])){++work.blocks;work.block_bytes+=block_length(source);}
  unsigned causes=0;if(!prior[6]&&bus->adpcm.half_irq)causes|=1;if(!prior[7]&&bus->adpcm.end_irq)causes|=2;if(causes&3)++work.adpcm_cause_groups;if(!prior[8]&&bus->vdc.irq1){causes|=4;++work.vdc_cause_groups;}
  const unsigned vector=cpu.irq_entries>entries?cpu.irq_vector:0;if(vector){require(vector==(entries==0?0xfff8:0xfff6),"Actual active IRQ priority differs");irq_frame(source,observe(),vector,recipe);}if(source.bytes[0]==0x40)rti_frame(observe(),recipe);
  if(source.pc==recipe.target){require(!(prior[4]&4)&&prior[8]&&prior[11]&&phase.at("vstate")==1&&phase.at("hstate")==1&&phase.at("sprite_count")==2&&!phase.at("burst")&&(phase.at("latched_cr")&128)&&phase.at("latched_mwr")==3&&phase.at("sat_pending")==0&&phase.at("bg_start")<=phase.at("hpos")&&phase.at("hpos")<phase.at("bg_end"),"Target did not enter genuine active HDW BG arbitration with two fetched sprites");require(vector==0xfff8&&cpu.vdc_wait_ticks>waits,"Target must actually wait and deliver IRQ1");}
  if(causes||vector||source.pc==recipe.target||source.pc==recipe.pre_dma||(source.pc>=0xf800&&source.pc<0xf8b0)||(window&&work.instructions<=16))journal.push_back({source,prior,cpu.ticks-ticks,cpu.vdc_wait_ticks-waits,vector,causes,observe(),phase});
 }

};
std::vector<std::uint8_t>read(const char*path){std::ifstream in(path,std::ios::binary);require(bool(in),"Checkpoint missing");return{std::istreambuf_iterator<char>(in),{}};}
void write(const char*path,const std::vector<std::uint8_t>&data){require(!std::filesystem::exists(path),"New checkpoint required");std::ofstream out(path,std::ios::binary);out.write(reinterpret_cast<const char*>(data.data()),data.size());require(bool(out),"Checkpoint write failed");}
void records(const std::vector<Record>&items){std::cout<<'[';bool first=true;for(const auto&r:items){std::cout<<(first?"":",")<<'{';source_json(std::cout,r.source);std::cout<<",\"before\":";vec(std::cout,r.before);std::cout<<",\"ticks\":"<<r.ticks<<",\"wait_ticks\":"<<r.waits<<",\"vector\":"<<r.vector<<",\"causes\":"<<r.causes<<",\"after\":";observation(std::cout,r.after);std::cout<<",\"active_before\":{";bool first_phase=true;for(const auto&[key,value]:r.active_before){std::cout<<(first_phase?"":",")<<'"'<<key<<"\":"<<value;first_phase=false;}std::cout<<"}}";first=false;}std::cout<<']';}
void witnesses(const std::vector<Witness>&items){std::cout<<'[';bool first=true;for(const auto&w:items){std::cout<<(first?"":",")<<'{';source_json(std::cout,w.source);std::cout<<",\"values\":";vec(std::cout,w.values);std::cout<<'}';first=false;}std::cout<<']';}
}
int main(int argc,char**argv){try{require(argc==9,"CASE ROM CUE CUT write|resume TIER CHECKPOINT CAPTURE");const auto&c=active_irq_case(argv[1]);const auto cut=std::stoul(argv[4]);require(cut<3,"Three natural cuts only");const std::string mode=argv[5],tier=argv[6];require((mode=="write"||mode=="resume")&&(tier=="native"||tier=="interpreter"),"Explicit mode/tier required");Adapter a(argv[2],argv[3],tier=="native",c);std::vector<std::uint8_t>saved;Work prefix;std::map<Source,std::uint64_t>prefix_hits;std::vector<Record>prefix_journal;std::vector<Witness>prefix_witnesses;
 if(mode=="write"){a.captured(std::string(argv[8])+".prefix.json",false);reach(a,cut_pc(a,c,cut));a.capture->finish();prefix=a.work;prefix_hits=a.sources;prefix_journal=a.journal;prefix_witnesses=a.witnesses;const auto reads=a.provider->reads;saved=pce::encode_checkpoint(*a.bus,a.cpu);require(reads==a.provider->reads,"Save read provider");write(argv[7],saved);}else{saved=read(argv[7]);pce::restore_checkpoint(*a.bus,a.cpu,saved);require(!a.provider->reads,"Restore read provider");}
 require(pce::encode_checkpoint(*a.bus,a.cpu)==saved&&a.pc()==cut_pc(a,c,cut),"Exact canonical checkpoint/cut roundtrip differs");const auto initial=a.observe();const auto origin_n=a.cpu.native_steps,origin_i=a.cpu.interpreter_steps,origin_b=a.cpu.native_block_steps+a.cpu.interpreter_block_steps,origin_nb=a.cpu.native_block_steps,origin_ib=a.cpu.interpreter_block_steps,origin_bytes=a.cpu.block_bytes,origin_frame=a.bus->vdc.video.sequence();const auto reads=a.provider->reads;
 a.captured(argv[8],true);if(mode=="resume")a.capture->set_checkpoint_origin(pce::checkpoint_hash(saved),a.cpu.ticks,origin_frame,origin_n,origin_i);finish(a,c);a.capture->finish();final_checks(a,c);require(a.cpu.guard_misses==0&&a.cpu.native_steps-origin_n==(a.native?a.work.instructions:0)&&a.cpu.interpreter_steps-origin_i==(a.native?0:a.work.instructions)&&a.cpu.block_bytes-origin_bytes==a.work.block_bytes&&a.cpu.native_block_steps-origin_nb==(a.native?a.work.blocks:0)&&a.cpu.interpreter_block_steps-origin_ib==(a.native?0:a.work.blocks),"Actual suffix execution tier/byte work differs");
 std::cout<<"{\"dma_counter_role\":\"captured-bytes\",\"vdc_counter_role\":\"completed-words\",\"case\":\""<<c.id<<"\",\"cut_id\":"<<cut<<",\"tier\":\""<<tier<<"\",\"mode\":\""<<mode<<"\",\"runtime_abi\":"<<pce::abi_version<<",\"prefix_native\":"<<origin_n<<",\"prefix_interpreted\":"<<origin_i<<",\"window_native\":"<<a.cpu.native_steps-origin_n<<",\"window_interpreted\":"<<a.cpu.interpreter_steps-origin_i<<",\"guard_misses\":0,\"provider_prefix\":"<<reads<<",\"provider_suffix\":"<<a.provider->reads-reads<<",\"prefix_blocks\":"<<origin_b<<",\"prefix_block_bytes\":"<<origin_bytes<<",\"origin_frame\":"<<origin_frame<<",\"checkpoint_sha256\":\""<<pce::checkpoint_hash(saved)<<"\",\"final_sha256\":\""<<pce::checkpoint_hash(pce::encode_checkpoint(*a.bus,a.cpu))<<"\",\"cut\":";observation(std::cout,initial);std::cout<<",\"final\":";observation(std::cout,a.observe());std::cout<<",\"prefix_work\":";work_json(std::cout,prefix);std::cout<<",\"window_work\":";work_json(std::cout,a.work);std::cout<<",\"prefix_hits\":";hits(std::cout,prefix_hits);std::cout<<",\"window_hits\":";hits(std::cout,a.sources);std::cout<<",\"prefix_journal\":";records(prefix_journal);std::cout<<",\"journal\":";records(a.journal);std::cout<<",\"prefix_provider_witnesses\":";witnesses(prefix_witnesses);std::cout<<",\"window_provider_witnesses\":";witnesses(a.witnesses);std::cout<<",\"ram\":";vec(std::cout,a.ram());std::cout<<",\"vram\":";vec(std::cout,a.vram());std::cout<<"}\n";return 0;
 }catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
